#include "../boundary-kernel.cpp"
#include <vector>
#include <cstdio>
#include <cstdlib>
#include <cstring>
using namespace showai_boundary;
static void require(bool b,const char*label){if(!b){std::fprintf(stderr,"owner delta failure %s\n",label);std::abort();}}
static void rectangle(SAInkPathCommand*out,double x){out[0]={SA_INK_MOVE,0,{x,0}};out[1]={SA_INK_LINE,0,{x+1,0}};out[2]={SA_INK_LINE,0,{x+1,1}};out[3]={SA_INK_LINE,0,{x,1}};out[4]={SA_INK_CLOSE,0,{}};}
static SABoundaryBudget limits(){SABoundaryBudget b{};b.max_commands=10;b.max_curves=8;b.max_pairs=100;b.max_cuts=10000;b.max_edges=100;b.max_leases=3;b.max_sources=2;b.max_paths=1;b.max_polynomial_degree=64;b.max_stored_bits=16384;b.max_polynomial_operations=5000000;b.max_limb_operations=1000000000;b.retained_bytes=8*1024*1024;b.workspace_bytes=8*1024*1024;return b;}
int main(int argc,char**argv){auto budget=limits();std::vector<uint64_t>state((sa_boundary_state_bytes()+7)/8),arena((budget.retained_bytes+budget.workspace_bytes)/8);require(sa_boundary_initialize(state.data(),uint32_t(state.size()*8),31,arena.data(),uint32_t(arena.size()*8),&budget)==0,"actual owner initialized");
 SABoundaryPath path{0,0,{0,0}};SAInkPathCommand commands[10];rectangle(commands,0);rectangle(commands+5,3);SABoundarySourceBlock source[2]{};for(uint32_t i=0;i<2;i++){source[i].key.words[0]=i+1;source[i].command_count=5;source[i].first_command=i*5;source[i].affine[0]=source[i].affine[3]=1;}
 SABoundaryLease a{},b{},c{},d{},noop{},failed{12,34,56,78,90},sentinel=failed;require(sa_boundary_prepare(state.data(),nullptr,&path,1,source,2,commands,10,&a)==0,"complete actual two-source base");
 SABoundarySourceMutation mutation{};mutation.source=source[1];mutation.source.first_command=0;rectangle(commands,6);require(sa_boundary_update(state.data(),&a,&mutation,1,commands,5,&b)==0,"actual public retained source update");SABoundarySnapshot reportB{};require(sa_boundary_snapshot(state.data(),b,&reportB)==0&&reportB.classifications==4&&reportB.source_commands==10,"public counts prove local side classification");
 double rectangles[12]={0,0,1,1,3,0,4,1,6,0,7,1},old[6],moved[6];require(sa_boundary_measure_coverage(state.data(),a,rectangles,3,old,3)==0&&sa_boundary_measure_coverage(state.data(),b,rectangles,3,moved,3)==0,"actual original-curve Green query through public leases");require(old[0]==1&&old[2]==1&&old[4]==0&&moved[0]==1&&moved[2]==0&&moved[4]==1,"old inflight source and new moved source both exact");
 rectangle(commands,99);require(sa_boundary_update(state.data(),&a,&mutation,1,commands,5,&failed)==SA_INK_INVALID&&!std::memcmp(&failed,&sentinel,sizeof failed),"late stale base atomic rejection");require(sa_boundary_measure_coverage(state.data(),b,rectangles,3,moved,3)==0&&moved[4]==1,"caller mutation never alters captured source");
 SABoundarySourceMutation duplicate[2]{};duplicate[0].operation=duplicate[1].operation=SA_BOUNDARY_REMOVE_SOURCE;duplicate[0].source.key=duplicate[1].source.key=source[1].key;require(sa_boundary_update(state.data(),&b,duplicate,2,nullptr,0,&failed)==SA_INK_INVALID&&!std::memcmp(&failed,&sentinel,sizeof failed),"literal duplicate mutation key rejected atomically");
 SABoundarySourceMutation batch[2]{};batch[0].source=mutation.source;batch[0].source.key.words[0]=3;batch[1].operation=SA_BOUNDARY_REMOVE_SOURCE;batch[1].source.key=source[1].key;rectangle(commands,9);require(sa_boundary_update(state.data(),&b,batch,2,commands,5,&c)==0,"valid final batch independent of insert-before-remove packet order");
 require(sa_boundary_update(state.data(),&c,batch,1,commands,5,&noop)==0&&!std::memcmp(&noop,&c,sizeof c),"actual unchanged capture works when all lease slots busy");require(sa_boundary_release(state.data(),noop)==0,"release no-op external lease");rectangle(commands,12);require(sa_boundary_update(state.data(),&c,batch,1,commands,5,&failed)==SA_INK_CAPACITY&&!std::memcmp(&failed,&sentinel,sizeof failed),"prepared/inflight lease budget actual failure");
 require(sa_boundary_release(state.data(),a)==0,"retire completed older inflight");require(sa_boundary_update(state.data(),&c,batch,1,commands,5,&d)==0,"retry identical actual intent after lease budget released");SABoundarySnapshot reportD{};require(sa_boundary_snapshot(state.data(),d,&reportD)==0&&reportD.classifications==4&&reportD.source_curves==8,"retained source does not reclassify unrelated arcs");
 batch[0].source.key.words[0]=4;rectangle(commands,20);require(sa_boundary_update(state.data(),&d,batch,1,commands,5,&failed)==SA_INK_CAPACITY&&!std::memcmp(&failed,&sentinel,sizeof failed),"actual final source capacity failure leaves current unchanged");
 SABoundaryEdge edges[8];require(sa_boundary_copy_edges(state.data(),d,0,8,edges,8)==0,"final actual curve consumers");double final_rectangles[12]={0,0,13,1,9,0,10,1,12,0,13,1},final_area[6];require(sa_boundary_measure_coverage(state.data(),d,final_rectangles,3,final_area,3)==0&&final_area[0]<=2.0/13&&final_area[1]>=2.0/13&&final_area[2]==0&&final_area[4]==1,"final exact Boolean Green result");
 uint32_t words=0;require(sa_boundary_copy_parameter(state.data(),d,edges[0].parameter_certificate[0],nullptr,0,&words)==0,"exact original-curve parameter proof sizing");std::vector<uint32_t>proof(words);require(sa_boundary_copy_parameter(state.data(),d,edges[0].parameter_certificate[0],proof.data(),words,&words)==0,"exact original-curve parameter proof copied");
 if(argc==2){FILE*f=std::fopen(argv[1],"wb");require(f,"parity output opened");uint32_t header[4]={0x53414431,uint32_t(sizeof(SABoundaryEdge)),uint32_t(sizeof(SABoundarySnapshot)),uint32_t(sizeof(SABoundaryLease))};require(std::fwrite(header,sizeof header,1,f)==1&&std::fwrite(&b,sizeof b,1,f)==1&&std::fwrite(&c,sizeof c,1,f)==1&&std::fwrite(&d,sizeof d,1,f)==1&&std::fwrite(&reportB,sizeof reportB,1,f)==1&&std::fwrite(&reportD,sizeof reportD,1,f)==1&&std::fwrite(edges,sizeof edges,1,f)==1&&std::fwrite(final_area,sizeof final_area,1,f)==1&&std::fwrite(&words,4,1,f)==1&&std::fwrite(proof.data(),4,words,f)==words,"write actual public Native delta output");std::fclose(f);}
 require(sa_boundary_destroy(state.data())==SA_INK_INVALID,"live inflight cannot be invalidated");require(sa_boundary_release(state.data(),b)==0&&sa_boundary_release(state.data(),c)==0&&sa_boundary_release(state.data(),d)==0&&sa_boundary_destroy(state.data())==0,"all actual lease generations retired and destroyed");std::printf("BOUNDARY_PUBLIC_DELTA_ATOMIC_OK classifications=4 unchanged_arcs=4\n");
}
